import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class CodeforcesVariant5 {

    public static int binarySearch(int val, int[] arr) {
        int startIdx = 0;
        int endIdx = arr.length - 1;
        while (startIdx <= endIdx) {
            int midIdx = (startIdx + endIdx) / 2;
            if (arr[midIdx] == val) return midIdx;
            if (val > arr[midIdx]) startIdx = midIdx + 1;
            else endIdx = midIdx - 1;
        }
        return -1;
    }

    public static void main(String[] args) throws IOException {
        InputStream inStream = System.in;
        BufferedReader br = new BufferedReader(new InputStreamReader(inStream));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int maxLen = 0, countWings = 0;
        String inputLine = br.readLine();
        char[] sequenceChars = inputLine.toCharArray();

        for (int i = 0; i < n; i++) {
            if (sequenceChars[i] != '_' && sequenceChars[i] != '(') {
                int segmentCount = 0;
                for (int j = i; j < n; j++) {
                    if (sequenceChars[j] != '_' && sequenceChars[j] != '(') segmentCount++;
                    if (sequenceChars[j] == '_' || sequenceChars[j] == '(' || j == n - 1) {
                        maxLen = Math.max(maxLen, segmentCount);
                        i = j;
                        break;
                    }
                }
            }
            if (sequenceChars[i] == '(') {
                int count = 0;
                for (int j = i; j < n; j++) {
                    if ((sequenceChars[j] == '_' || sequenceChars[j] == ')') && count > 0) {
                        countWings++;
                        count = 0;
                    }
                    if (sequenceChars[j] == ')') {
                        i = j;
                        break;
                    }
                    if (sequenceChars[j] != '_' && sequenceChars[j] != '(') count++;
                }
            }
        }
        System.out.println(maxLen + " " + countWings);
    }
}
